import{_ as t,o as s,c as i,ag as n}from"./chunks/framework.DQQHyi2x.js";const u=JSON.parse('{"title":"Isolated runtime kit","description":"","frontmatter":{},"headers":[],"relativePath":"guide/isolated-runtime-kit.md","filePath":"guide/isolated-runtime-kit.md"}'),a={name:"guide/isolated-runtime-kit.md"};function o(r,e,d,h,c,l){return s(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="isolated-runtime-kit" tabindex="-1">Isolated runtime kit <a class="header-anchor" href="#isolated-runtime-kit" aria-label="Permalink to &quot;Isolated runtime kit&quot;">​</a></h1><p>The isolated runtime kit starts, proves and tears down one isolated runtime for a provider live check. A harness issue uses it instead of designing its own environment. Every check runs the CLI under test against a local stub model, inside its own network namespace, with Synth City&#39;s normal team launch and Agent Mail registration.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/isolated-runtime-kit.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     --root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/kit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --provider</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude-code</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/cli</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/isolated-runtime-kit.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/kit</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/isolated-runtime-kit.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   --root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/kit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--timeout </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">120]</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> COMMAND...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/isolated-runtime-kit.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   --root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/kit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--keep]</span></span></code></pre></div><h2 id="what-up-starts" tabindex="-1">What <code>up</code> starts <a class="header-anchor" href="#what-up-starts" aria-label="Permalink to &quot;What \`up\` starts&quot;">​</a></h2><ul><li><strong>Two namespace anchors.</strong> The outer anchor runs <code>unshare --user --map-root-user --net</code>. It brings up <code>lo</code>, which must be the only network link, so nothing inside the kit can reach another host or another Synth City. The inner anchor maps back to the caller&#39;s uid and gid. Both start from an empty environment, so no token, socket or identity of the caller&#39;s session reaches the namespaces.</li><li><strong>An isolated Synth City backend.</strong> It has its own root, HOME, SQLite database and private tmux socket, a synthetic operator token, and an allowlisted environment. It doesn&#39;t build or serve the UI.</li><li><strong>A stub model provider</strong> (<code>scripts/runtime-kit/stub_provider.py</code>) on <code>127.0.0.1</code>. It answers the OpenAI-compatible chat API with a fixed reply, and its log keeps a hash of each request, never prompt text.</li><li><strong>The CLI under test.</strong> It&#39;s installed under its provider&#39;s binary name, for example <code>claude</code> for <code>claude-code</code>. Every other harness name resolves to a fake, so no host CLI can start, and <code>gh</code> is disabled. The kit then installs Agent Mail for the provider, creates a team preset with one slot and launches it through the normal launch API. That writes the real pane binding; the CLI then registers from its pane through the normal Agent Mail endpoint.</li></ul><p><code>up</code> prints one JSON line: the namespace, the links, the uid, the pane, the registration and binding read from the kit&#39;s database, the stub request count, and the kit&#39;s process ids. It never prints a token.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Deadline</th><th>What it does</th></tr></thead><tbody><tr><td><code>up</code></td><td>90 s (<code>RUNTIME_KIT_UP_DEADLINE</code>)</td><td>Preflight (10 s), stub (5 s), backend health (30 s), launch and registration (30 s). A failure stops every process and keeps the root for its logs.</td></tr><tr><td><code>status</code></td><td>15 s</td><td>Checks the instance, every recorded process, the backend&#39;s health and the registration before it writes anything. It then builds the evidence and the summary in a new attempt directory and publishes them; see <a href="#evidence">Evidence</a> for the commit point and exit codes.</td></tr><tr><td><code>exec</code></td><td>120 s by default, at most 600 s</td><td>Runs a command inside the namespaces with the kit&#39;s environment.</td></tr><tr><td><code>down</code></td><td>30 s</td><td>Stops every process of the instance, including ones started later inside its namespace, proves none remains, checks the evidence manifest, and removes the root (<code>--keep</code> keeps it). If it can&#39;t prove cleanup, it fails as incomplete and keeps the root.</td></tr></tbody></table><p><strong>Exit codes:</strong> 0 means success, 1 a failure, a deadline or an incomplete proof, and 2 a refusal.</p><h2 id="ownership-and-cleanup" tabindex="-1">Ownership and cleanup <a class="header-anchor" href="#ownership-and-cleanup" aria-label="Permalink to &quot;Ownership and cleanup&quot;">​</a></h2><p>Each <code>up</code> creates one instance with a random id. <code>state/instance.json</code> (a private file) records that id, the root directory&#39;s identity and the kit&#39;s namespaces. <code>status</code>, <code>exec</code> and <code>down</code> refuse (exit 2) before any signal, write or deletion when:</p><ul><li>the record is missing or malformed, or isn&#39;t a private file of the caller;</li><li>it was copied from another root;</li><li>it names a host namespace.</li></ul><p><strong>Ownership comes only from records.</strong> The kit records every process it starts with its pid, start time, a SHA-256 of its command line, and its parent&#39;s pid and start time. Each process has one expected parent:</p><ul><li>the launcher is the parent of the outer anchor;</li><li>the outer anchor is the parent of the inner anchor;</li><li>the inner anchor is the parent of the tmux server, the stub and the backend (it starts them itself);</li><li>the tmux server is the parent of the CLI pane.</li></ul><p>A process counts as the kit&#39;s only when every recorded field matches and its parent is the recorded process of its expected parent role. It must also be in the kit&#39;s recorded namespaces. Before those are recorded, only the anchors may exist, and only in their own non-host namespaces. A process in a host namespace never counts. When a process re-executes, only its recorded command line may change.</p><p><strong>Signals.</strong> Every signal opens a pidfd first, proves the full recorded identity, and then signals through that pidfd. Without pidfd support, or on any mismatch, nothing is signalled. The launcher is never signalled; it exits with the outer anchor.</p><p><strong><code>down</code></strong> first computes a read-only plan. It refuses before any signal, keeping the root and the anchors, if any recorded process fails its proof, or if any unrecorded or unreadable process is in the kit&#39;s network namespace. Otherwise it stops the CLI, the stub, the backend, the tmux server, the inner anchor and the outer anchor, in that order.</p><p><strong>A root is never reused.</strong> A root left by <code>down --keep</code> or by a failed <code>up</code> is refused by the next <code>up</code>; run <code>down</code> to remove it.</p><h2 id="evidence" tabindex="-1">Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to &quot;Evidence&quot;">​</a></h2><p><code>status</code> publishes these files in <code>ROOT/evidence/</code> (a link to the latest complete attempt in <code>ROOT/evidence.d/</code>), with <code>MANIFEST.sha256</code>:</p><ul><li><code>namespaces.json</code></li><li><code>links.txt</code></li><li><code>processes.txt</code></li><li><code>pane.json</code></li><li><code>registration.json</code></li><li><code>environment-names.json</code>, holding variable names only, never values</li><li><code>stub-requests.jsonl</code></li><li><code>summary.json</code></li></ul><p><code>down</code> refuses to finish if the manifest no longer matches.</p><p><strong>Publication.</strong> <code>status</code> builds each attempt in a new <code>evidence.d/&lt;16 hex&gt;</code> directory and then replaces the <code>ROOT/evidence</code> link with one atomic rename. That rename is the commit point.</p><ul><li><strong>Before the commit point,</strong> a failure removes only this run&#39;s own attempt directory and temporary link, after checking that each is its own direct, non-symlink entry. The published link and every earlier attempt stay unchanged; <code>status</code> exits 1 (&quot;incomplete … the published evidence is unchanged&quot;).</li><li><strong>After the commit point,</strong> the new evidence is published and stays published. <code>status</code> then prints the summary. If printing fails, it exits 1 with &quot;published, but the summary could not be printed&quot;. Exit 0 means published and printed.</li><li><strong>Earlier attempts are kept.</strong> <code>status</code> never deletes them and never follows a link to delete anything; <code>down</code> removes them with the whole root.</li><li><code>status</code> refuses (exit 2), writing nothing, if <code>evidence.d</code> or an attempt is a symlink or isn&#39;t a direct child of the root.</li></ul><h2 id="safety-rules" tabindex="-1">Safety rules <a class="header-anchor" href="#safety-rules" aria-label="Permalink to &quot;Safety rules&quot;">​</a></h2><p>The kit refuses, with exit 2, when:</p><ul><li><code>SYNTH_CITY_URL</code> or a Synth City Mail credential variable is set;</li><li>the root is not empty and has no <code>.deck-runtime-kit</code> marker;</li><li>the root path is longer than 96 bytes, because the tmux socket path must fit in 108;</li><li>no real tmux executable is found (a launcher script is not accepted);</li><li>the network namespace has any link other than <code>lo</code>;</li><li>the inner namespace doesn&#39;t map to the caller&#39;s uid and gid;</li><li>the two-step namespace entry doesn&#39;t land in the anchors&#39; namespaces;</li><li>a recorded process id now has another start time, so it may belong to another process.</li></ul><p><strong>Namespace entry is two-step.</strong> The kit enters through the outer anchor, which owns the network namespace, and then the inner one. A single <code>nsenter</code> into the inner anchor is refused by the kernel. Before it enters a namespace, the kit proves both anchors as described in <a href="#ownership-and-cleanup">Ownership and cleanup</a>.</p><h2 id="using-it-for-a-live-check" tabindex="-1">Using it for a live check <a class="header-anchor" href="#using-it-for-a-live-check" aria-label="Permalink to &quot;Using it for a live check&quot;">​</a></h2><ol><li>Write the check as commands run with <code>exec</code>, or let the CLI under test act from its pane.</li><li>Run <code>up</code>, then <code>status</code>, and keep the printed summary and the evidence manifest as the check&#39;s evidence.</li><li>Run <code>down</code> and keep its result as proof of cleanup.</li></ol><p>The end-to-end test <code>backend/tests/test_isolated_runtime_kit.py</code> runs a fake provider CLI (<code>scripts/runtime-kit/fake_cli.sh</code>) through these steps.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Linux only.</strong> The kit needs unprivileged user and network namespaces, plus <code>tmux</code>, <code>unshare</code>, <code>nsenter</code>, <code>ip</code>, <code>timeout</code> and <code>setsid</code>. The kit&#39;s own checks without namespaces (the model, refusal, fake-CLI and stub tests) run on every host.</li><li><strong>Not on the hosted <code>ubuntu-latest</code> runner as configured.</strong> The runner denies the namespace setup (<code>unshare: write failed /proc/self/uid_map: Operation not permitted</code>). The log shows the denial, not its cause. There, each namespace-dependent test skips with <code>capability unavailable: uid_map</code>, and the namespace path is proved by one local run in the owner&#39;s leased workspace, with evidence on the PR for review.</li><li><strong>One OS user.</strong> Factory members share one OS user, so ownership is proved by the instance id and namespace, never by the user id alone.</li><li><strong>Local checks only.</strong> The stub model doesn&#39;t model a real provider; a real-provider check is a separate decision with its own approval.</li><li><strong>One kit per root.</strong> The ports (18780 for the backend, 18781 for the stub) belong to the kit&#39;s own network namespace, so separate kits don&#39;t collide.</li></ul>`,33)])])}const m=t(a,[["render",o]]);export{u as __pageData,m as default};
